{"code": "export async function main(input: unknown) {
  const counts: Record<string, number> = {};
  let cursor: string | undefined = undefined;
  let pages = 0;
  let total = 0;
  while (true) {
    const res = await sdk.github.listCommits(cursor ? { cursor } : {});
    pages++;
    for (const c of res.commits) {
      const key = c.authorEmail;
      counts[key] = (counts[key] ?? 0) + 1;
      total++;
    }
    if (!res.nextCursor) break;
    cursor = res.nextCursor;
    if (pages > 500) throw new Error("too many pages");
  }
  return { pages, total, counts };
}"}
